-- Please note not all available settings / options are set here.
-- For a full list, see the wiki: https://wiki.hypr.land/Configuring/Start/

--
-- Dependencies:
-- - Menu: wofi
-- - Terminal: Alacritty
-- - Bar: Waybar
-- - Lock: swaylock
-- - Wallpaper: hyprpaper
--

--
-- Load External Variables
--
-- Generated by the colors-hypr.lua pywal template. Run `wal -R` after a
-- theme change (or after editing the template) to regenerate this file.
local colors = dofile(os.getenv("HOME") .. "/.cache/wal/colors-hypr.lua")

--
-- Variables
--
local mainMod = "SUPER"
local alt = "ALT"

-- Vim Movement Keys
local left, right, up, down = "h", "l", "k", "j"

local terminal = "alacritty"
local menu = "wofi --show drun"
local lockscreen = "swaylock --screenshots --indicator --clock --effect-blur 5x2 --fade-in 0.25"

-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Environment-variables/ for more
hl.env("XCURSOR_SIZE", "24")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")

-- For all categories, see https://wiki.hypr.land/Configuring/Basics/Variables/ for more
hl.config({
    input = {
        kb_layout = "us",
        kb_variant = "",
        kb_model = "",
        kb_options = "",
        kb_rules = "",

        follow_mouse = 1,

        touchpad = {
            natural_scroll = true,
        },

        sensitivity = 0, -- -1.0 - 1.0, 0 means no modification.
    },

    general = {
        gaps_in = 20,
        gaps_out = 10,
        border_size = 2,

        -- Use imported colors from wal cache
        col = {
            inactive_border = { colors = { colors.background, colors.backgroundAlpha }, angle = 45 },
            active_border   = { colors = { colors.color2, colors.color2Alpha }, angle = 45 },
        },

        layout = "dwindle",
    },

    decoration = {
        rounding = 10,

        blur = {
            enabled = true,
            size = 3,
            passes = 1,
        },

        shadow = {
            enabled = true,
            range = 4,
            render_power = 3,
            color = 0xee1a1a1a,
        },
    },

    animations = {
        enabled = true,
    },

    master = {
        -- See https://wiki.hypr.land/Configuring/Layouts/Master-Layout/ for more
        new_status = "slave",
    },

    misc = {
        -- Disabling the hyprland_logo is what allows the background to be
        -- displayed without showing the logo (or "hyprchan") before the image is in memory
        disable_hyprland_logo = true,
    },
})

-- Default animations, see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/ for more
hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })

hl.animation({ leaf = "windows",     enabled = true, speed = 7,  bezier = "myBezier" })
hl.animation({ leaf = "windowsOut",  enabled = true, speed = 7,  bezier = "default", style = "popin 80%" })
hl.animation({ leaf = "border",      enabled = true, speed = 10, bezier = "default" })
hl.animation({ leaf = "borderangle", enabled = true, speed = 8,  bezier = "default" })
hl.animation({ leaf = "fade",        enabled = true, speed = 7,  bezier = "default" })
hl.animation({ leaf = "workspaces",  enabled = true, speed = 6,  bezier = "default" })

-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Gestures/ for more
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

-- Example per-device config
-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Devices/ for more
hl.device({
    name = "epic-mouse-v1",
    sensitivity = -0.5,
})

-- Example window rules
-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/ for more
-- hl.window_rule({ name = "float-kitty", match = { class = "^(kitty)$" }, float = true })

--
-- Base Level Binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
--
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd(menu))
-- Use Alt + L for lock, instead of Mod + L due to Mod + L being used for focus movement.
hl.bind(alt .. " + L", hl.dsp.exec_cmd(lockscreen))

hl.bind(mainMod .. " + SHIFT + Q", hl.dsp.window.kill())
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exit())

hl.bind(mainMod .. " + F", hl.dsp.window.float({ action = "toggle" }))

--
-- Screenshots
--
-- NOTE: the old hyprland.conf used "PRINT_a" / "PRINT_s" / "PRINT_c" as key names, but
-- those were never valid X11 keysyms (the real keysym is just "Print") -- hyprlang silently
-- dropped these binds on load instead of erroring, so they likely never worked. The Lua
-- config loader is stricter and refuses to reload on an unknown keysym, so I've remapped
-- them onto the real "Print" key differentiated by modifier. Remap these if you'd prefer
-- different keys.
-- Screenshot All
hl.bind("Print", hl.dsp.exec_cmd("grim ~/Pictures/$(date +'%Y-%m-%d-%H%M%S').png"))
-- Screenshot Selected Area
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("grim -g \"$(slurp)\" ~/Pictures/$(date +'%Y-%m-%d-%H%M%S')-selected.png"))
-- Screenshot Currently Focused Monitor
-- Also swapped `swaymsg` (a Sway command, doesn't work under Hyprland) for hyprctl's own
-- focused-monitor query.
hl.bind("CTRL + Print", hl.dsp.exec_cmd("grim -o $(hyprctl monitors -j | jq -r '.[] | select(.focused) | .name') ~/Pictures/$(date +'%Y-%m-%d-%H%M%S')-focused.png"))

--
-- Moving around:
--
-- Move focus with mainMod + vim movement keys
hl.bind(mainMod .. " + " .. left,  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + " .. right, hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + " .. up,    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + " .. down,  hl.dsp.focus({ direction = "down" }))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

--
-- Audio
--
-- Just Alsa Mixer
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("amixer -q set Master 2%+ unmute"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("amixer -q set Master 2%- unmute"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("amixer -q set Master toggle"))

-- Pulse Audio
-- hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pulseaudio-ctl up"))
-- hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pulseaudio-ctl down"))
-- hl.bind("XF86AudioMute", hl.dsp.exec_cmd("pulseaudio-ctl mute"))
-- hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("pulseaudio-ctl mute-input"))

-- hl.bind("XF86AudioMute", hl.dsp.exec_cmd("pactl set-sink-mute @DEFAULT_SINK@ toggle"))
-- hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pactl set-sink-volume @DEFAULT_SINK@ -5%"))
-- hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pactl set-sink-volume @DEFAULT_SINK@ +5%"))

-- Microphone
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("pactl set-source-mute @DEFAULT_SOURCE@ toggle"))
-- Logitech mouse macro to trigger mic mute on windows should also mute default mic
-- NOTE: the old hyprland.conf referenced "$alt_Control_Shift", which was never a defined
-- variable, so this bind was already non-functional before this migration. Reconstructed
-- as the modifiers the variable name implies (ALT+CTRL+SHIFT). Remap if that's not right.
hl.bind("ALT + CTRL + SHIFT + m", hl.dsp.exec_cmd("pactl set-source-mute @DEFAULT_SOURCE@ toggle"))

-- Players
-- play-pause on both media buttons, as this laptop doesnt have them
-- This is for bluetooth headsets which are bad at tracking whether or not song is playing
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"))

--
-- Device Specific Configuration
--
-- cd linux-dots repo
-- cd ./hypr
-- ln -s ./brian-arch ./current-computer
require("current-computer.config")

-- Execute At Launch
--
-- - Import GTK Theme Settings
-- - Policy Kit
-- - Wallpaper
-- - Thunar Daemon
-- - Waybar
hl.on("hyprland.start", function()
    hl.exec_cmd("$HOME/.config/sway/custom-scripts/import-gsettings.sh")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("thunar --daemon")
    hl.exec_cmd("hyprpaper")
    hl.exec_cmd("waybar")
end)
